<?php $slots=['home_before_featured'=>'قبل البطاقات الرئيسية','home_after_featured'=>'بعد البطاقات الرئيسية','home_before_latest'=>'قبل أحدث المقالات','home_after_latest'=>'بعد أحدث المقالات','home_before_categories'=>'قبل التصنيفات','home_after_categories'=>'بعد التصنيفات','article_after_cover'=>'بعد صورة المقال','article_before_related'=>'قبل المقالات المشابهة','footer_before'=>'قبل الفوتر']; ?>
<section class="panel"><div class="panel-head"><div><span class="panel-kicker">تخطيط مرن</span><h2>أقسام الصور والإعلانات</h2></div></div><form method="post" action="/admin/blocks/save" class="form-grid"><?=csrf_field()?><input type="hidden" name="id" value="0"><label>النوع<select name="type"><option value="image">صورة / بانر</option><option value="ad">إعلان موجود</option></select></label><label>مكان الظهور<select name="slot"><?php foreach($slots as $k=>$v):?><option value="<?=$k?>"><?=e($v)?></option><?php endforeach;?></select></label><label>اللغة<select name="locale"><option value="*">كل اللغات</option><?php foreach(enabled_locales() as $code=>$info):?><option value="<?=$code?>"><?=e(language_flag($code).' '.language_name($code))?></option><?php endforeach;?></select></label><label>الترتيب<input type="number" name="sort_order" value="0"></label><label>العنوان<input name="title"></label><label>الصورة من المكتبة<select name="image_url"><option value="">بدون / رابط مخصص أدناه</option><?php foreach($media as $m):?><option value="<?=e($m['path'])?>"><?=e($m['title']?:$m['original_name']?:basename($m['path']))?></option><?php endforeach;?></select></label><label>أو رابط صورة مخصص<input name="image_url_custom" placeholder="https://..."></label><label>رابط عند الضغط<input name="target_url"></label><label>الإعلان<select name="ad_id"><option value="">بدون</option><?php foreach($ads as $a):?><option value="<?=$a['id']?>">#<?=$a['id']?> <?=e($a['label']?:$a['slot'])?></option><?php endforeach;?></select></label><label class="check"><input type="checkbox" name="active" checked> مفعّل</label><button class="btn btn-primary">حفظ القسم</button></form></section>
<section class="panel"><div class="panel-head"><h2>الأقسام الحالية</h2></div><div class="ad-list-v4"><?php foreach($blocks as $b):?><article class="ad-admin-card"><div><span class="status <?=$b['active']?'s-active':'s-blocked'?>"><?=$b['active']?'مفعّل':'متوقف'?></span><strong><?=e($b['title']?:($slots[$b['slot']]??$b['slot']))?></strong><small><?=e($slots[$b['slot']]??$b['slot'])?> · <?=e($b['type']==='ad'?'إعلان':'صورة')?> · <?=e($b['locale']==='*'?'كل اللغات':$b['locale'])?></small></div><form method="post" action="/admin/blocks/delete" onsubmit="return confirm('حذف هذا القسم؟')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$b['id']?>"><button class="btn btn-danger">حذف</button></form></article><?php endforeach;?></div></section>
